	"dataSources": {
		"ds_B2KBGtyi": {
			"type": "ds.search",
			"options": {
				"query": "index=winevents source=\"wineventlog:security\" (EventCode=4624 Security_ID=\"PROGRAM*\" Logon_Type=2 OR Logon_Type=7 OR Logon_Type=10)\n| dedup _time host user\n| eval Logon_Type=case(Logon_Type==2, \"Interactive\", Logon_Type==7, \"Unlock\", Logon_Type==10, \"Remote Interactive\")\n| eval Time = strftime(_time, \"%Y-%m-%d %H:%M:%S\")\n| table Time host user Logon_Type",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"name": "Successful Logons Windows"
		},
